async def act(page):
    import asyncio
    import re

    # KB function reasoning:
    # - export_customers_csv_via_grid exists but exports the Customers grid. Our task is to compute
    #   the number of cancelled orders per customer from the Orders history. The Customers export
    #   won't provide order cancellation counts, so the KB helper is not useful for this task.

    # Give UI a moment to stabilize from the current state
    await asyncio.sleep(0.3)

    # 1) Increase view-per-page to 200 if available to reduce paging
    try:
        view_cb = page.get_by_role("combobox").filter(
            has=page.get_by_role("option", name="200")
        ).nth(0)
        # ensure the locator exists before interacting
        if await view_cb.count() > 0:
            await view_cb.select_option(label="200")
            await asyncio.sleep(0.6)
    except Exception:
        # non-fatal; continue even if we can't change page size
        pass

    # 2) Set the Status filter to 'Canceled' using the combobox that contains that option
    try:
        status_cb = page.get_by_role("combobox").filter(
            has=page.get_by_role("option", name="Canceled")
        ).nth(0)
        if await status_cb.count() > 0:
            await status_cb.select_option(label="Canceled")
            await asyncio.sleep(0.2)
    except Exception:
        # continue even if this fails
        pass

    # 3) Click the Search button scoped to the 'Reset Filter Search' cell (use full get_by_role path)
    try:
        search_btn = page.get_by_role("cell", name="Reset Filter Search").get_by_role("button", name="Search").nth(0)
        await search_btn.click()
        await asyncio.sleep(0.8)
    except Exception:
        # fallback: any page-level Search button
        try:
            fallback_search = page.get_by_role("button", name="Search").nth(0)
            await fallback_search.click()
            await asyncio.sleep(0.8)
        except Exception:
            pass

    # 4) Determine total pages from the header cell that contains the 'Go to Next page' link
    total_pages = 1
    header_cell = None
    try:
        header_cell = page.get_by_role("cell").filter(
            has=page.get_by_role("link", name="Go to Next page")
        ).nth(0)
        if await header_cell.count() > 0:
            text = await header_cell.inner_text()
            m = re.search(r"of\s+(\d+)\s+pages", text, re.IGNORECASE)
            if m:
                total_pages = int(m.group(1))
            else:
                m2 = re.search(r"of\s+(\d+)", text, re.IGNORECASE)
                if m2:
                    total_pages = int(m2.group(1))
    except Exception:
        # If unable to determine, fall back to 1 page
        total_pages = 1

    # 5) Locate the Orders table (the table that contains a header cell with name 'Order #')
    orders_table = None
    tables = page.get_by_role("table")
    tcount = await tables.count()
    for i in range(tcount):
        t = tables.nth(i)
        try:
            if await t.get_by_role("cell", name="Order #").count() > 0:
                orders_table = t
                break
        except Exception:
            continue

    if orders_table is None:
        # nothing to compute
        print("0")
        return

    # 6) Find header row inside orders_table and determine column indices for 'Bill to Name' and 'Status'
    rows = orders_table.get_by_role("row")
    rows_count = await rows.count()
    header_row = None
    for ri in range(rows_count):
        r = rows.nth(ri)
        try:
            if await r.get_by_role("cell", name="Order #").count() > 0:
                header_row = r
                break
        except Exception:
            continue
    if header_row is None:
        header_row = rows.nth(0)

    header_cells = header_row.get_by_role("cell")
    hc_count = await header_cells.count()
    bill_idx = None
    status_idx = None
    for ci in range(hc_count):
        try:
            txt = (await header_cells.nth(ci).inner_text() or "").strip().lower()
        except Exception:
            txt = ""
        if "bill to name" in txt or "bill to" in txt:
            bill_idx = ci
        if "status" in txt:
            status_idx = ci
    # sensible defaults if not found
    if bill_idx is None:
        bill_idx = 4
    if status_idx is None:
        # choose a reasonable default (Status typically near the end)
        status_idx = max(0, hc_count - 2)

    # 7) Iterate through each page (bounded by total_pages) and count canceled orders per customer
    cancels_by_customer = {}
    for page_num in range(1, total_pages + 1):
        # Re-resolve rows for current page
        rows = orders_table.get_by_role("row")
        row_count = await rows.count()
        for ri in range(row_count):
            row = rows.nth(ri)
            try:
                # identify data rows by presence of the 'View' link
                if await row.get_by_role("link", name="View").count() == 0:
                    continue
            except Exception:
                continue

            # get cells for this row
            cells = row.get_by_role("cell")
            ccount = await cells.count()

            # read status cell if available
            try:
                status = (await cells.nth(status_idx).inner_text()).strip().lower() if status_idx < ccount else ""
            except Exception:
                status = ""
            if "cancel" not in status:
                # skip non-canceled (defensive; filter should have been applied)
                continue

            # read customer name from bill_to column (fallback heuristics if missing)
            try:
                if bill_idx < ccount:
                    cust = (await cells.nth(bill_idx).inner_text()).strip()
                else:
                    # fallback: find a likely name cell
                    cust = ""
                    for k in range(ccount):
                        t = (await cells.nth(k).inner_text()).strip()
                        if t and not t.startswith("000000") and not t.startswith("$"):
                            cust = t
                            break
                    if not cust:
                        cust = "<unknown>"
            except Exception:
                cust = "<unknown>"

            cancels_by_customer[cust] = cancels_by_customer.get(cust, 0) + 1

        # If more pages remain, click 'Go to Next page' (scoped to header_cell) and wait
        if page_num < total_pages:
            try:
                # re-resolve header_cell to avoid stale locator
                header_cell = page.get_by_role("cell").filter(
                    has=page.get_by_role("link", name="Go to Next page")
                ).nth(0)
                await header_cell.get_by_role("link", name="Go to Next page").click()
                await asyncio.sleep(0.8)
                # re-resolve orders_table for the new page
                tables = page.get_by_role("table")
                orders_table = None
                tcount = await tables.count()
                for i in range(tcount):
                    t = tables.nth(i)
                    try:
                        if await t.get_by_role("cell", name="Order #").count() > 0:
                            orders_table = t
                            break
                    except Exception:
                        continue
                if orders_table is None:
                    break
            except Exception:
                # if we can't advance, stop early
                break

    # 8) Compute the maximum cancellations across customers and print only that number
    if not cancels_by_customer:
        print("0")
    else:
        max_cancels = max(cancels_by_customer.values())
        print(str(max_cancels))

